from build import save
rows=[
(431,['洛城复活识萧御，放狠话后离去，小雨解缠；萧实际交易稀装给妹。公会观察盾战风神与风隐练习，范围近身与持续能力破贼；主要敌刀剑苍冥，英雄职业偏光环不等于单挑强。'],['赶追求者本场完成，后续履诺尚无更多呈现。'],[],26603,26680),
(432,['萧赵陪练六组，自己不加状态而敌满buff、开眼，贼六冰七单弱双强且不宜插第三人。公会嬉笑中开始练习。'],['重新磨合新套装及队友技能。'],[],26681,26752),
(433,['战争狂怒免控亦令自身控制无效；赵治疗水缚接裂爆，对方冰盾救人。赵水舞水牢新技、借萧遮挡视线，锁定水龙终结。萧评控制输出不同步、缺瞬控，战术依组合而异。'],['二人配合胜一组，评议不把己战法作通用答案。'],['贼六冰七互换及赵匕首属源误。'],26753,26814),
(434,['六队皆胜未用比蒙天使。萧说一挑50只因丛林特定人地，强队竞技至多5。十精英起哄二对十，关探隐扩场五倍试极限。'],['展示战绩适用边界，额外训练有利规则并非正式公平赛。'],[],26815,26891),
(435,['风野嘱保密后准用天使末技。三近夹萧远程压赵，比蒙当掩体；巫解咒、萨满即时治巫，敌协作有反应。'],['没有因主角新装而抹去敌配合。'],[],26892,26968),
(436,['萧重击9807杀暗巫、赵回满；图腾反8000。德欲复巫，萧顶雷12789触腰盾脚踢断，退到7%而赵忙自保，拉开后回满。召60%分影。'],['巫亡且战复被断；主角需牺牲血与撤离换功能优势。'],[],26969,27045),
(437,['风野回顾因赵让萧新手黑赛自负盈亏，赌收入130亿与前196异。分身锁熊德，本体重击13876接赵梦魇10123击杀；敌冰雹覆盖压制，分影断追牺牲。风乱复风鸦但其3分钟战复受断不能救巫，比蒙天使被杀。'],['双方资源消耗，主角末技即将用而非已赢。'],[],27046,27118),
(438,['血腥6000群、杀戮5000、满能战争咆哮后萧赵双亡，杀六人白虎余四远程，萧明确认输。竞技三轮含3小时无通讯缩荒漠、分组挑战、十强循环；萧首轮放同会等高分，赵群杀首第一。'],['二对十输但逼全资源；全服赛正式启动。'],[],27119,27189),
(439,['赵首轮百万分第一，萧9万多名均晋。萧1v1 S、二人SS；先组后三天团赛。猴子SS、旋律旋风双人队。风神组三人练胜SS，萧不给万能策略。二人16秒胜德战。'],['大量杀人积分不等于单挑排序；组合互补体现。'],[],27190,27270),
(440,['公众承认赵实力又研究录像。死神知风知羽杀手组最后收5312万，各留2000余，1312万给老五结婚。知风诱敖龙先砍后凭3分钟自卫杀，普通匕弃尸为签名；后来敖龙被杀回50装空，委托人未明。两人拟竞技收手。'],['新对手以场外实绩插入；收手是意向。'],[],27271,27341),
(441,['二人挑战第五炽焰玄冰，敌火爆发单次9000与冰控逼赵治疗；双方尊重仍全力。水缚咒绞杀出血使冰必死，转火胜。二人第五、风神3v3第一、魔域刺刀5v5第一为决赛资格。'],['资格取到，冠军未定。'],[],27342,27404),
(442,['萧挑战糖糖女地精奥术，先按貌年龄误判后看片正视。糖13岁、神佑多奖和五下位神戒套，14岁以下无血痛保护；奥术精灵+60%、半魔半精神，30码照隐范围高伤。'],['装备强弱与年龄偏见进入同一比赛。'],[],27405,27470),
(443,['糖地精缩小器五分之一仍施法约30秒，器价300万；萧21%血以旧购神圣血瓶道具技能回满、嗅觉欺诈脱精灵。糖缩小结束三板斧用尽主动认输，哥哥身份待揭。萧排名第四次日决赛。'],['糖装备优势未弥补套路单一，萧资格已成。'],[],27471,27528),
(444,['战胜后城市喜庆与NPC奖励涨；污染母星十二年治理和新星船票。风野借赵练团被萧拒以保私时。酒吧爱情之心活动，主持枫夜看燕琳；燕见萧赵亲密主动来，后悔想挽回又退缩。'],['旧恋人重逢，未复合。'],['去母星船票与拟赴新星叙述疑错。'],27529,27589),
(445,['萧明确即使无赵也不与燕复合，伤如白墙钉孔。上台幽默飞刀献女友，蒙眼60余匕射双心一箭，末尾微歪自评。燕只转述听人说他幼时跟老特工学刀，自己不甚清楚。'],['飞刀公共表演让贫穷时期被嫌的能力重新获赞；师承非确证刀伤起因。'],[],27590,27658),
(446,['萧客气划清燕边界并离开，爱情之心实际得并交赵：+1000血、增益10%、指定爱人感应位置、女限。枫夜未获燕联系方式。各族NPC仪仗入冥夜竞技，十强名单与公会占比，风野六千人自费入非挪会费。'],['爱情之心交付完成；主角技公开视频推动其他贼。'],[],27659,27722),
(447,['风野给小雨五票照看前排。苍冥以赵为赌注挑衅，萧拒拿伴侣下注，改赌全部装毁不可交易、归零永久退游。猴子出拳触3分自卫，群友护；炎神反向羞辱提出赌约。'],['赌约升级重大不可逆代价；赵先安抚而非同意自己为筹码。'],[],27723,27804),
(448,['苍冥怕炎神未知实力不应赌离开；橘子再戏炎神。炎神自证糖糖哥哥，因冠军外奖励无用令妹不决赛，文本此称14异前13。循环赛胜得1分。橘子、小刀、柠檬、猴子连四轮认输，猴守不对恩人动刀誓。第五轮刀剑。'],['熟人关系改变积分路径，不可把四胜均算实战取胜。'],[],27805,27880),
(449,['刀剑为挑战刺刀转追萧，压迫技熟练免控；萧逃脱解围召比蒙，对方白熊弱一阶，兽狂化可抗比蒙免控。双方巨招碰撞，萧余12000刀21000，两兽亦伤。'],['正面强敌迫资源，狂化终会弱提供拖延解。'],[],27881,27966),
(450,['两兽互换亡，萧隐拖狂化一分钟保影子底牌；刀大范围偶中显萧，最后10秒追、先知束缚限隐且血低35%。末日斩本可1–2万却狂化已过仅2108，刀认输萧得分。萧自省藏招险翻盘，刀坦荡受败。'],['第五胜正式实战达成；保留资源带来风险而非全在算中。'],[],27967,28047),
]
d={
'worldbuilding':[['免控状态使自身控制亦无效；双人配合能以队友控制补自己限制，控制与输出窗口要一致。','fact',[433,26753,26814]],['正式赛三轮由荒漠无通讯积分筛至等级组挑战、十强循环；资格名次与最终冠军不同。','fact',[438,27141,27189],[439,27190,27231],[448,27855,27858]],['糖的14岁以下无血痛保护和神佑奖，与地精缩小器、神圣血瓶道具分别组成不同资源；411黑赛禁任何药剂特殊道具，443全服赛使用回血道具，赛事是否同域未解释。','inference',[442,27405,27470],[443,27477,27495]],['狂化一分钟后仅一成属性，先知束缚只打低于35%血隐形目标；限制与技能施放时序实际定胜负。','fact',[450,27990,28000],[450,28027,28042]]],
'characters':[['赵在练习治疗、遮视线、控制输出与召唤独立作决策；首轮百万第一让公众开始承认她而不只看恋人身份。','fact',[433,26753,26814],[438,27170,27189],[440,27271,27282]],['萧公开承认一挑50有丛林和对手条件、二对十仍输；他有能力边界而非作者需把所有战绩无条件推广。','fact',[434,26815,26846],[438,27119,27141]],['燕因嫌贫土疏远留下不可复的伤，萧明确无赵也不复合，感情选择不是只由现女友挡住。','fact',[445,27590,27606],[446,27660,27678]],['刀剑保有临场技与坦荡败者人格，糖有好胜、哭、依赖哥哥三板斧，两个败者不以同一羞辱模板处理。','inference',[443,27500,27524],[449,27883,27925],[450,28039,28045]]],
'plot':[['练习先解释一挑50条件、二对十完整展开失利，再竞技按分组规则推进，资源上限先可见后用于正式对决。','inference',[434,26815,26891],[438,27119,27189],[449,27923,27964]],['糖哥哥从不许说姓名的悬念到炎神本人自认回收；主角先猜刀剑苍冥为误猜，不将猜测覆盖揭晓。','fact',[443,27513,27524],[448,27840,27843]],['飞刀能力在旧恋疏离与现恋赠礼之间跨用：被燕嫌土的技艺成为向赵表达的公共表演。','inference',[445,27590,27598],[445,27607,27655],[446,27668,27673]],['前四轮非战取分削去重复战，刀剑一战完整处理胜负，保留底牌也是危险选择。','inference',[448,27863,27878],[450,27997,28043]]],
'style':[['训练把血量百分比、技能窗口和职业功能同步展示，9807、12789、7%等数值改变当下选择，而不只是报强度。','inference',[436,26969,27045],[437,27046,27118]],['白墙钉孔和飞刀心形把不可逆旧伤与重新表达爱情转成可见物；意象服务具体关系选择。','inference',[445,27590,27606],[445,27628,27655]],['竞技刀气裂地与兽化肉身的宏大视觉同血条、时限细算并用，末日斩击先写威势后以2108反差揭时序。','inference',[449,27942,27963],[450,28030,28040]],['炎神的反讽以性羞辱和同性污名为笑料，具有角色缓解效果但不宜作为原样可学的幽默。','inference',[447,27800,27802],[448,27806,27839]]],
'narrative':[['近距战斗与风野观望交替，让不知影子技能的公众、知底牌公会与读者保有不同知识。','inference',[435,26892,26904],[437,27046,27057],[450,27997,28043]],['转入知风知羽独立场外线，先行为建立杀手履历再让其成为2v2名单，避免只用标签宣布强敌。','inference',[440,27283,27341],[446,27705,27706]],['公开录像既给主角成名，也让全职业学习及对手准备；名声带来学习扩散和暴露成本双结果。','fact',[440,27271,27282],[446,27703,27706],[448,27816,27816]]],
'dialogue':[['萧关于控制输出同步和依敌组合调整的赛后评议，是带例子的诊断，不给所有人同一答案。','inference',[433,26798,26814],[439,27227,27245]],['萧拒以女友作赌注后把苍冥的怕了反问还回去，赌约把人格侮辱变成后续胜负的执行承诺。','fact',[447,27767,27781]],['侥幸措辞延续谦逊公共形象，但450旁白同时承认时限幸运与保留实力；人物措辞不等于完整战因。','inference',[450,28036,28045]]],
'pacing':[['六组陪练快写到一组细写，再扩二对十完整资源消耗；正式赛初筛加速、强敌细写形成不同展示粒度。','inference',[432,26701,26752],[434,26815,26891],[438,27119,27189],[449,27881,27966]],['竞技前夜转酒吧旧恋与表演，给持续战斗一个关系停顿，再由各族仪仗把规模抬回国家赛事。','inference',[444,27529,27589],[446,27688,27720]],['先公告冠军选人愿景再循环赛，熟人认输省去已知结果，刀剑前期强压与最后十秒拖长让机制解释本身成为悬念。','inference',[448,27848,27878],[450,28001,28042]]],
'themes':[['旧爱拒绝不是证明财富才让她后悔，文本以自尊被伤及不可逆关系为理由；但燕只悔而少独立行动的收束仍有限。','inference',[445,27590,27606],[446,27660,27681]],['女性不可作赌注的明确拒绝与赵自称被弃认命、男性争护等占有语言并存，不能将全文的爱情价值直接当现代关系范本。','inference',[444,27569,27572],[447,27772,27781]],['从孤独胜者到公会协作、对手共享技艺、猴子守恩人誓，成名不只增加个人数值，也把人情带进赛制。','inference',[446,27703,27717],[447,27766,27791],[448,27876,27877]]],
'continuity':[['一挑50是特定丛林敌人与资源，二对十有利规则仍双亡；不可用前战直接证明任何强敌竞技可灭50。','fact',[434,26823,26846],[438,27119,27141]],['糖糖自称13，448旁白称14；433训练若干贼六冰七互称、赵匕首与437风野130亿（415为196）保留源异常，不新造身份或金额。','fact',[433,26753,26814],[437,27046,27057],[442,27405,27470],[448,27840,27843]],['神圣血瓶是早购道具技能，411黑赛禁任何药剂特殊道具，443全服赛确用回血道具；两赛事适用规则是否不同未说明，照实保留疑点。','fact',[411,25207,25210],[443,27492,27495]],['洛城431离去且小雨解缠，不等于此后永远遵守；飞刀师承445仅燕转述，未解释15/16岁刀伤。','fact',[431,26603,26625],[445,27646,27651]]],
}
c=[dict(key='xiao-yu',name='萧御',aliases=[],summary='二对十全技仍负，后1v1晋十强、循环前四轮对手认输，第五刀剑实战胜；对燕明确划界，爱情之心交赵。',goals=['赢全服1v1及与赵2v2','守住关系边界','使对手看不清底牌'],changes=['承认群战依条件','隐藏影子险被刀剑翻盘而自省','用飞刀公开献现伴侣'],relationships=['燕只留朋友边界','与赵协同更精确','猴子守不动刀之誓'],knowledge=['刀剑狂化限时、先知束缚低血隐形限制'],source_anomalies=['飞刀师承非确证','敌阵营称谓有错'],evidence=[[434,26823,26846],[438,27119,27141],[445,27590,27606],[446,27668,27673],[450,28027,28045]]),dict(key='zhao-lanxin',name='赵岚馨',aliases=['夜岚'],summary='水舞水牢等新技与治疗形成互补，首轮百万分第一，2v2到十强；收爱情之心实际属性与感应爱人功能。',goals=['与萧共同竞技','维持亲密关系'],changes=['公众开始承认独立战力','旧恋重会中主动安抚且体贴离去'],relationships=['既配合萧也有自身团队赛','不能因萧替她拒借团而推她已表意见'],knowledge=['燕的后悔与萧旧伤','师承尚是转述'],source_anomalies=['433持匕首应为杖'],evidence=[[433,26753,26814],[439,27190,27208],[440,27271,27282],[446,27668,27686]]),dict(key='tangtang',name='糖糖',aliases=[],summary='女地精奥术神佑之女，装强年龄小依哥哥三板斧，缩小器结束后主动认输；哥哥炎神让她不决赛。与男玩家堕落的糖果不同人。',goals=['证明自己能胜主角','想冠军'],changes=['主角正视其技能而非按外貌相让','套路耗尽认输'],relationships=['炎神亲口认其哥哥','称艾斐尔姐姐'],knowledge=['知道自己后续不会打，口头不服'],source_anomalies=['442自称13、448旁白14'],evidence=[[442,27405,27470],[443,27500,27524],[448,27840,27843]]),dict(key='yan-lin',name='燕琳',aliases=[],summary='重逢后后悔曾嫌萧贫土伤自尊，欲复合却未说成，主角明确无赵也不复合、止于朋友。对飞刀师承仅二手听闻。',goals=['接近并挽回旧情'],changes=['看其今成就与幽默技艺后悔','被礼貌拉开距离后离线'],relationships=['枫夜想追但未获联系方式','与赵有礼貌无实质争抢'],knowledge=['幼时飞刀老特工传闻并不甚清楚'],source_anomalies=[],evidence=[[444,27575,27587],[445,27590,27606],[445,27646,27655],[446,27660,27681]]),dict(key='dao-jian',name='刀剑',aliases=[],summary='大元帅兽人战士，白熊、狂化和先知束缚等对贼技；原想挑战刺刀后目标转萧，狂化时间耗完败而坦荡认输。',goals=['与最高盗贼公平比试'],changes=['准备的终招因过时限失威而败','保强敌尊严'],relationships=['萧赞其技巧与坦荡'],knowledge=['萧逃脱已知仍一时忽略；不知道影子底牌'],source_anomalies=[],evidence=[[449,27883,27928],[450,28027,28045]])]
